        "content": "{\n  \"$schema\": \"http://json-schema.org/draft-07/schema#\",\n  \"title\": \"ci-self-heal Skill 输出契约\",\n  \"description\": \"ci-self-heal Skill 输出 markdown 报告需按本 schema 描述的字段顺序与字段集. 不直接做 JSON-Schema 校验 (输出本身是 markdown), 但用于 SDK 形态 Step 7 边界回归 + 单测 prompt 一致性断言.\",\n  \"type\": \"object\",\n  \"required\": [\n    \"failure_class\",\n    \"confidence\",\n    \"verdict\",\n    \"root_cause_hypotheses\",\n    \"related_files\"\n  ],\n  \"additionalProperties\": false,\n  \"properties\": {\n    \"failure_class\": {\n      \"type\": \"string\",\n      \"enum\": [\n        \"test_failure\",\n        \"lint_failure\",\n        \"build_failure\",\n        \"type_error\",\n        \"dependency_missing\",\n        \"config_error\",\n        \"flaky\",\n        \"timeout\",\n        \"unknown\"\n      ],\n      \"description\": \"8 类候选 + unknown 兜底, 由 classify-failure.ts 决定\"\n    },\n    \"confidence\": {\n      \"type\": \"string\",\n      \"enum\": [\"high\", \"medium\", \"low\"],\n      \"description\": \"对应 classify confidence: high≥0.75 / medium 0.5-0.75 / low<0.5\"\n    },\n    \"verdict\": {\n      \"type\": \"string\",\n      \"enum\": [\n        \"likely_pr_caused\",\n        \"likely_flaky\",\n        \"likely_environment\",\n        \"needs_human\"\n      ],\n      \"description\": \"根据 PR diff 关联 + 启发式信号决定; LLM 不确定时必须返回 needs_human (RL-007 守护)\"\n    },\n    \"root_cause_hypotheses\": {\n      \"type\": \"array\",\n      \"minItems\": 0,\n      \"maxItems\": 3,\n      \"items\": {\n        \"type\": \"object\",\n        \"required\": [\"priority\", \"title\", \"evidence\", \"why\", \"suggested_fix\"],\n        \"properties\": {\n          \"priority\": { \"type\": \"integer\", \"minimum\": 1, \"maximum\": 3 },\n          \"title\": { \"type\": \"string\", \"minLength\": 1, \"maxLength\": 200 },\n          \"evidence\": {\n            \"type\": \"string\",\n            \"description\": \"必含 file:line 或 log line 引用; LLM 不能编造未在 log 中出现的失败 (RL-007)\"\n          },\n          \"why\": { \"type\": \"string\" },\n          \"suggested_fix\": {\n            \"type\": \"string\",\n            \"description\": \"可执行步骤 (命令 / diff 草稿 / 配置改动); 涉及测试断言时必须标记 'needs human review' (RL-006)\"\n          }\n        }\n      }\n    },\n    \"related_files\": {\n      \"type\": \"array\",\n      \"items\": {\n        \"type\": \"object\",\n        \"required\": [\"file\", \"reason\"],\n        \"properties\": {\n          \"file\": { \"type\": \"string\" },\n          \"line\": { \"type\": \"integer\", \"minimum\": 1 },\n          \"reason\": { \"type\": \"string\" }\n        }\n      }\n    },\n    \"skipped_checks\": {\n      \"type\": \"array\",\n      \"items\": { \"type\": \"string\" },\n      \"description\": \"Skill 跳过的检查项 + 跳过原因 (例如 'PR diff 不可用 → 跳过 is_pr_caused 判定')\"\n    },\n    \"redacted_count\": {\n      \"type\": \"integer\",\n      \"minimum\": 0,\n      \"description\": \"RL-002 守护: log 中检测到的凭证数, 输出已 redact\"\n    }\n  }\n}\n",
