        "content": "{\n  \"$schema\": \"http://json-schema.org/draft-07/schema#\",\n  \"$id\": \"incident-rca/output-schema\",\n  \"type\": \"object\",\n  \"required\": [\"incident_summary\", \"severity\", \"hypotheses\", \"evidence_chain\", \"action_plan\"],\n  \"properties\": {\n    \"incident_summary\": {\n      \"type\": \"object\",\n      \"required\": [\"title\", \"severity\", \"impact_scope\", \"duration_estimate\"],\n      \"properties\": {\n        \"title\": { \"type\": \"string\" },\n        \"severity\": { \"type\": \"string\", \"enum\": [\"P0\", \"P1\", \"P2\", \"P3\"] },\n        \"impact_scope\": { \"type\": \"string\" },\n        \"duration_estimate\": { \"type\": \"string\" },\n        \"services_affected\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } }\n      }\n    },\n    \"severity\": { \"type\": \"string\", \"enum\": [\"P0\", \"P1\", \"P2\", \"P3\"] },\n    \"hypotheses\": {\n      \"type\": \"array\",\n      \"items\": {\n        \"type\": \"object\",\n        \"required\": [\"rank\", \"hypothesis\", \"likelihood\", \"evidence_refs\"],\n        \"properties\": {\n          \"rank\": { \"type\": \"integer\", \"minimum\": 1 },\n          \"hypothesis\": { \"type\": \"string\" },\n          \"likelihood\": { \"type\": \"string\", \"enum\": [\"high\", \"medium\", \"low\"] },\n          \"evidence_refs\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } },\n          \"root_service\": { \"type\": [\"string\", \"null\"] }\n        }\n      },\n      \"minItems\": 1,\n      \"maxItems\": 5\n    },\n    \"evidence_chain\": {\n      \"type\": \"array\",\n      \"items\": {\n        \"type\": \"object\",\n        \"required\": [\"evidence_id\", \"type\", \"source\", \"content_summary\"],\n        \"properties\": {\n          \"evidence_id\": { \"type\": \"string\" },\n          \"type\": { \"type\": \"string\", \"enum\": [\"log\", \"metric\", \"trace\", \"commit\", \"adr\", \"config\"] },\n          \"source\": { \"type\": \"string\" },\n          \"content_summary\": { \"type\": \"string\" },\n          \"timestamp\": { \"type\": [\"string\", \"null\"] }\n        }\n      }\n    },\n    \"action_plan\": {\n      \"type\": \"object\",\n      \"required\": [\"hotfix\", \"mitigation\", \"long_term\"],\n      \"properties\": {\n        \"hotfix\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } },\n        \"mitigation\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } },\n        \"long_term\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } }\n      }\n    },\n    \"skipped_checks\": {\n      \"type\": \"array\",\n      \"items\": {\n        \"type\": \"object\",\n        \"properties\": {\n          \"check\": { \"type\": \"string\" },\n          \"reason\": { \"type\": \"string\" }\n        }\n      }\n    }\n  }\n}\n",
